(3,  'WEEKEND',          'Écritures atypiques (hors période)',    'Détecte les écritures manuelles saisies le week-end, un jour férié ou hors heures ouvrées', 'moyenne'),
(4,  'DOUBLONS',         'Détection de doublons',                 'Repère les écritures avec même compte, même montant et même pièce', 'elevee'),
(5,  'CHRONO_INVERSEE',  'Chronologie inversée',                  'Détecte les ruptures de séquence entre le numéro d''écriture et la date dans un même journal', 'moyenne'),
(6,  'ROUND_NUMBER',     'Montants ronds suspects',                'Signale les montants ronds (multiples de 1000) en fréquence anormale', 'faible'),
(7,  'TOP_SAISISSEURS',  'Analyse des utilisateurs saisisseurs',  'Classement des 10 principaux saisisseurs en volume et montant', 'faible'),
(8,  'ANNULATION_RAPIDE','Écritures rapidement annulées',         'Détecte les écritures contre-passées dans un délai très court', 'elevee'),
(9,  'FIN_PERIODE',      'Concentration de fin de période',       'Analyse la concentration anormale d''écritures en fin de mois/exercice', 'moyenne'),
(10, 'REVUE_ANALYTIQUE', 'Revue analytique N vs N-1',              'Variations significatives des soldes de comptes par rapport à l''exercice précédent', 'moyenne'),
(11, 'SOLDE_ANORMAL',    'Soldes anormaux',                       'Comptes avec un solde de sens inhabituel (ex : fournisseur débiteur) ou sans mouvement', 'elevee'),
(12, 'SCORING_RISQUE',   'Scoring de risque par écriture',        'Score composite agrégeant les résultats des différents tests', 'moyenne');
